mapper.select:
select IFNULL(sum(t.amount), 0) from coupon_bill_pay_detail t

    AND t.inservice = true

        and DATE_FORMAT(t.crt_time,'%Y-%m-%d') >= DATE_FORMAT(#{query.startDate},'%Y-%m-%d')


        and DATE_FORMAT(t.crt_time,'%Y-%m-%d') <= DATE_FORMAT(#{query.endDate},'%Y-%m-%d')


        and t.org_id = #{query.orgId}


        and t.account_item_id = #{query.payId}
